# Submit the pension contribution associated
# with this Salary Slip.

pension_name = frappe.db.get_value(
    "MITC Pension Contribution",
    {
        "salary_slip": doc.name,
        "docstatus": 0
    },
    "name"
)

if pension_name:

    pension = frappe.get_doc(
        "MITC Pension Contribution",
        pension_name
    )

    pension.submit()

# Cancel the pension contribution associated
# with this Salary Slip.

pension_name = frappe.db.get_value(
    "MITC Pension Contribution",
    {
        "salary_slip": doc.name,
        "docstatus": 1
    },
    "name"
)

if pension_name:

    pension = frappe.get_doc(
        "MITC Pension Contribution",
        pension_name
    )

    pension.cancel()

# Deleted linked pension contribution record when related salary slip is also deleted

pension_name = frappe.db.get_value(
    "MITC Pension Contribution",
    {
        "salary_slip": doc.name,
        "docstatus": 0
    },
    "name"
)

if pension_name:

    frappe.delete_doc(
        "MITC Pension Contribution",
        pension_name,
        ignore_permissions=True
    )

# Cancel all submitted MITC Pension Contribution
# records belonging to this Payroll Entry.

pension_contributions = frappe.get_all(
    "MITC Pension Contribution",
    filters={
        "payroll_entry": doc.name,
        "docstatus": 1
    },
    pluck="name"
)

for pension_name in pension_contributions:

    pension = frappe.get_doc(
        "MITC Pension Contribution",
        pension_name
    )

    if pension.docstatus == 1:
        pension.cancel()
